import numpy as np
L=np.log(eps)
E={'1':np.ones_like(eps),'e':eps,'e2':eps**2,'1/e':1/eps,'L':L,'L/e':L/eps,'eL':eps*L,'L2':L**2,'1/e2':1/eps**2,'e3':eps**3}
for maxT in [2,3,4]:
    for Esel in [['1','e','1/e','L','L/e'],['1','e','e2','1/e','L','L/e','eL'],['1','e','1/e','L','L/e','L2','e2','1/e2']]:
        feats=[E[e]*T**k for e in Esel for k in range(maxT+1)]
        A=np.column_stack(feats)
        c=np.linalg.lstsq(A,sigma,rcond=None)[0]
        print(maxT,Esel, np.mean((sigma-A@c)**2)/np.var(sigma))
